export function getLocaleFromPathname(pathname: string): WfmLocale { const segment = pathname.split('/')[1]; return isWfmLocale(segment) ? segment : DEFAULT_LOCALE }
export function localizedPath(locale: WfmLocale, pathname: string) { const withoutLocale = pathname.replace(/^\/(?:en|es|pt|fr|de)(?=\/|$)/, '') || '/'; const cleanPath = withoutLocale === '/' ? '' : withoutLocale.replace(/^\/+/, ''); return locale === DEFAULT_LOCALE ? `/${cleanPath}` : `/${locale}${cleanPath ? `/${cleanPath}` : ''}` }
export function translate(locale: WfmLocale, key: string) { return TRANSLATIONS[locale][key] ?? PUBLIC_TRANSLATIONS[locale][key] ?? TRANSFER_TRANSLATIONS[locale][key] ?? EXTRA_TRANSLATIONS[locale][key] ?? PLAYER_PROFILE_TRANSLATIONS[locale][key] ?? PLAYER_PAGE_TRANSLATIONS[locale][key] ?? PAGE_TRANSLATIONS[locale][key] ?? SCOUTING_TRANSLATIONS[locale][key] ?? SCOUTING_REPORT_TRANSLATIONS[locale][key] ?? TRANSLATIONS[DEFAULT_LOCALE][key] ?? EXTRA_TRANSLATIONS[DEFAULT_LOCALE][key] ?? PLAYER_PROFILE_TRANSLATIONS[DEFAULT_LOCALE][key] ?? PLAYER_PAGE_TRANSLATIONS[DEFAULT_LOCALE][key] ?? PAGE_TRANSLATIONS[DEFAULT_LOCALE][key] ?? SCOUTING_TRANSLATIONS[DEFAULT_LOCALE][key] ?? SCOUTING_REPORT_TRANSLATIONS[DEFAULT_LOCALE][key] ?? key }